import {defaults,applyPreloads,validate,simulate,sheets,weekStart,weekKey,dateNum,dateStr,kinds} from './model.js';
const seed=await fetch('seed.json').then(r=>{if(!r.ok)throw Error('Could not load supplied demand.');return r.json()});
const KEY='americase-akro-planner-v1';let state=defaults(seed),tab='overview',result,selectedWeek=weekKey(state.settings.start),demandMode='sheets',chartDays=84,showAll=false;
try{const saved=localStorage.getItem(KEY);if(saved)state=applyPreloads(validate(JSON.parse(saved)))}catch(e){notice('Saved plan could not be loaded. The supplied demand is shown. Import a backup if available.')}
selectedWeek=weekKey(state.settings.start);
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2});
const dt=(s,year=false)=>new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',...(year?{year:'numeric'}:{}),timeZone:'UTC'});
const label=k=>k==='thin'?'3/4 inch':'1 1/8 inch';
const titles={overview:['Inventory outlook','Demand, curing and available stock. One daily view.'],demand:['Weekly demand','Enter order quantities or Akro sheet requirements by part and week.'],daily:['Daily plan & counts','Review cart loads, shutdowns and actual closing inventory.'],setup:['Setup & shutdowns','Set the starting position, capacity and operating calendar.']};
function notice(message){setTimeout(()=>{const t=$('#toast');if(t){t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',5000)}},0)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saved').textContent='Saved in this browser'}catch{ $('#saved').textContent='Export a backup to save';notice('Browser storage is unavailable. Use Export backup to keep your changes.')}}
function change(fn){const before=structuredClone(state);try{fn();validate(state);render();save()}catch(e){state=before;$('#error').hidden=false;$('#error').textContent=e.message;notice(e.message)}}
function modal(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal()}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function banner(){return !state.settings.verified?`<div class="banner"><strong>Starting position needs confirmation.</strong> Ready stock and initial oven loads default to zero. Enter today's position in <button class="button small secondary" data-tab="setup">Setup</button> before using this as an operating plan.</div>`:''}
function chart(kind,rows){if(!rows.length)return '<div class="chart-empty">No dates in this horizon.</div>';const g=state.settings,W=560,H=200,L=35,R=15,T=12,B=30,max=Math.max(g[kind+'Target'],...rows.map(r=>Math.max(r.inv[kind],r.backlog[kind])),1)*1.12;const X=i=>L+i/(Math.max(1,rows.length-1))*(W-L-R),Y=n=>T+(H-T-B)*(1-n/max);
 let grid='';for(let i=0;i<4;i++){let n=max*i/3,y=Y(n);grid+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#e7edf1"/><text x="${L-6}" y="${y+3}" text-anchor="end">${fmt(n)}</text>`}
 const line=fn=>rows.map((r,i)=>`${X(i)},${Y(fn(r))}`).join(' '),color=kind==='thin'?'#16837e':'#5267a2';let closed='';rows.forEach((r,i)=>{if(r.closed)closed+=`<rect x="${X(i)}" y="${T}" width="${Math.max(1,(W-L-R)/rows.length)}" height="${H-T-B}" fill="#fff0db"/>`});
 let ticks=[0,Math.floor((rows.length-1)/2),rows.length-1].map(i=>`<text x="${X(i)}" y="${H-10}" text-anchor="middle">${dt(rows[i].date)}</text>`).join('');
 return `<svg class="chart" data-chart="${kind}" data-dates="${esc(rows.map(r=>r.date).join(','))}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${label(kind)} available inventory and unserved demand over time">${closed}${grid}<line x1="${L}" y1="${Y(g[kind+'Target'])}" x2="${W-R}" y2="${Y(g[kind+'Target'])}" stroke="#9ba9b5" class="point-target"/><polyline points="${line(r=>r.inv[kind])}" fill="none" stroke="${color}" stroke-width="2.5"/><polyline points="${line(r=>r.backlog[kind])}" fill="none" stroke="#ca8638" stroke-width="1.8"/>${ticks}</svg><div class="legend"><span><b style="background:${color}"></b>Ready stock</span><span><b style="background:#ca8638"></b>Unserved demand</span><span><b style="background:#9ba9b5"></b>Target</span></div><div class="chart-hover" id="hover-${kind}">Hover over the chart for a daily balance. Shading = waterjet shutdown.</div>`;
}
function overview(){const g=state.settings,row=result.rows.find(r=>r.date===g.asOf)||result.rows[0],plot=result.rows.slice(0,chartDays===0?undefined:chartDays),last=result.rows.at(-1),wrows=showAll?result.weeks:result.weeks.slice(0,12);
 const ready=k=>`<div class="card"><div class="kpi-label">${label(k)} ready stock <span class="chip ${k}">${fmt(g[k+'Cure'])}-day cure</span></div><div class="kpi-number">${fmt(row.inv[k])}<span style="font-size:13px;font-weight:400;letter-spacing:0"> sheets</span></div><div class="kpi-sub">Target ${fmt(g[k+'Target'])} · ${fmt(row.pipeline[k])} in replenishment</div></div>`;
 return banner()+`<div class="toolbar"><div class="inline"><strong>Daily snapshot</strong><input type="date" data-setting="asOf" value="${g.asOf}" min="${g.start}" max="${g.end}"><span class="chip">${row.key}</span></div><span class="muted small">Forecast horizon: ${dt(g.start,true)} – ${dt(g.end,true)}</span></div><div class="kpis">${ready('thin')}${ready('thick')}<div class="card"><div class="kpi-label">Unserved demand <span class="chip ${row.backlog.thin+row.backlog.thick>0?'bad':'good'}">${row.backlog.thin+row.backlog.thick>0?'Waiting':'Clear'}</span></div><div class="kpi-number">${fmt(row.backlog.thin+row.backlog.thick)}</div><div class="kpi-sub">${fmt(row.backlog.thin)} thin · ${fmt(row.backlog.thick)} thick sheet equivalents</div></div><div class="card"><div class="kpi-label">Cured, awaiting full pallet</div><div class="kpi-number">${fmt(row.waiting.thin+row.waiting.thick)}</div><div class="kpi-sub">${fmt(row.waiting.thin)} thin · ${fmt(row.waiting.thick)} thick; unavailable to withdraw</div></div></div><div class="toolbar"><h2>Inventory projection</h2><select id="chartDays"><option value="28" ${chartDays===28?'selected':''}>Next 4 weeks</option><option value="84" ${chartDays===84?'selected':''}>Next 12 weeks</option><option value="0" ${chartDays===0?'selected':''}>Full horizon</option></select></div><div class="charts">${kinds.map(k=>`<section class="card"><div class="card-head"><h2>${label(k)} Akro</h2><span class="chip ${k}">${fmt(g[k+'Target'])} target</span></div>${chart(k,plot)}</section>`).join('')}</div><div class="card table-card"><div class="card-head"><h2>Weekly balance</h2><button class="button secondary small" id="allWeeks">${showAll?'Show first 12':'Show all weeks'}</button></div><p class="table-note">Daily demand remains due during shutdowns. Unserved demand carries forward; it is not counted as negative stock.</p><div class="scroll"><table><thead><tr><th>Week / dates</th><th>Thin demand</th><th>Thick demand</th><th>Carts thin / thick</th><th>Ready thin</th><th>Ready thick</th><th>Unserved</th><th>WJ down</th></tr></thead><tbody>${wrows.map(w=>`<tr><td class="datecell"><strong>${w.key}</strong><span>${dt(w.start)} – ${dt(w.end)}</span></td><td>${fmt(w.demand.thin)}</td><td>${fmt(w.demand.thick)}</td><td>${w.carts.thin} / ${w.carts.thick}</td><td>${fmt(w.inv.thin)}</td><td>${fmt(w.inv.thick)}</td><td class="${w.backlog.thin+w.backlog.thick>0?'bad':''}">${fmt(w.backlog.thin+w.backlog.thick)}</td><td>${w.closed} days</td></tr>`).join('')}</tbody></table></div></div><div class="card" style="margin-top:20px"><h3>What this forecast assumes</h3><p class="section-note">Demand is spread evenly across all seven days of each supplied week, advanced by ${g.lead} downstream lead days. Loads occur at day-end; a full cure is followed by unloading on the next morning, plus ${g.transfer} transfer days. ${g.withdrawCap>0?`Combined withdrawals are limited to ${g.withdrawCap} sheets per open day.`:'No catch-up withdrawal limit is set; open-day withdrawals are limited only by available stock.'} ${g.batchSize}-sheet pallets are released together. Oven checks enforce cart counts, not physical fit or unload sequence.</p><p class="section-note">At horizon end: ${fmt(last.inv.thin)} thin and ${fmt(last.inv.thick)} thick ready sheets; ${fmt(last.backlog.thin+last.backlog.thick)} unserved sheet equivalents. <button class="button small secondary" data-tab="setup">Edit assumptions</button></p></div>`;
}
function demand(){const total=state.parts.reduce((s,p)=>s+state.weeks.reduce((a,w)=>a+sheets(p,w.key),0),0);return `<div class="toolbar"><div class="inline"><select id="demandMode"><option value="sheets" ${demandMode==='sheets'?'selected':''}>Total_AKRO sheets</option><option value="qty" ${demandMode==='qty'?'selected':''}>Order quantities</option></select><span class="small muted">${state.parts.length} parts · ${state.weeks.length} demand weeks · ${fmt(total)} total sheets</span></div><div class="inline"><button class="button secondary small" id="addPart">+ Part</button><button class="button secondary small" id="addWeek">+ Week</button><button class="button small" id="bulk">Paste demand</button></div></div><div class="banner info">${demandMode==='sheets'?'<strong>Sheet demand view.</strong> Blue-bordered cells are direct Total_AKRO inputs. Other cells calculate quantity × sheets/case. Clear a blue cell to return to the calculated value.':'<strong>Order quantity view.</strong> Editing a quantity clears that cell’s sheet override, so its Total_AKRO recalculates.'} Weekly dates are ISO weeks. Thickness and sheet factors are editable; initial factors come from the latest supplied totals.</div><div class="card table-card"><div class="scroll"><table class="demand"><thead><tr><th class="sticky">Part number</th><th>Akro</th><th>Sheets / case</th>${state.weeks.map(w=>`<th>${w.key}<br><span class="small">${dt(w.date)}</span></th>`).join('')}<th>Total sheets</th></tr></thead><tbody>${state.parts.map((p,i)=>`<tr><td class="sticky"><strong>${esc(p.id)}</strong></td><td><select data-thickness="${i}"><option value="thin" ${p.thickness==='thin'?'selected':''}>3/4 inch</option><option value="thick" ${p.thickness==='thick'?'selected':''}>1 1/8 inch</option></select></td><td><input class="partfactor" data-factor="${i}" type="number" step="any" min="0.000001" value="${p.factor}"></td>${state.weeks.map(w=>{const ov=Object.hasOwn(p.overrides,w.key);return `<td><input aria-label="${esc(p.id)} ${w.key} ${demandMode}" class="${demandMode==='sheets'&&ov?'override':''}" data-demand="${i}" data-week="${w.key}" type="number" min="0" step="any" value="${demandMode==='qty'?(p.qty[w.key]||0):(ov?p.overrides[w.key]:'')}" placeholder="${demandMode==='sheets'?fmt(sheets(p,w.key)):''}" title="${ov?'Direct sheet override':'Calculated from order quantity'}"></td>`}).join('')}<td><strong>${fmt(state.weeks.reduce((s,w)=>s+sheets(p,w.key),0))}</strong></td></tr>`).join('')}${kinds.map(k=>`<tr class="totals"><td class="sticky">${label(k)} TOTAL_AKRO</td><td></td><td></td>${state.weeks.map(w=>`<td>${fmt(state.parts.filter(p=>p.thickness===k).reduce((s,p)=>s+sheets(p,w.key),0))}</td>`).join('')}<td>${fmt(state.parts.filter(p=>p.thickness===k).reduce((s,p)=>s+state.weeks.reduce((a,w)=>a+sheets(p,w.key),0),0))}</td></tr>`).join('')}</tbody></table></div></div><div class="card" style="margin-top:20px"><h3>Import reconciliation</h3><div class="metrics"><span>Supplied total<b>2,603.45 sheets</b></span><span>Current total<b>${fmt(total)} sheets</b></span><span>Difference from source<b>${fmt(total-2603.45)} sheets</b></span></div><p class="section-note">All 16 supplied parts and all 19 demand weeks are loaded. Total_AKRO beside a week was assigned to that preceding week only. Missing weekly sheet totals were derived from the part’s grand-total Akro ÷ grand-total quantity. New or changed inputs intentionally change the reconciliation.</p></div>`}
function daily(){const rows=result.rows.filter(r=>r.key===selectedWeek);return `<div class="toolbar"><div class="inline"><button class="button secondary small" id="prevWeek">←</button><select id="dailyWeek">${result.weeks.map(w=>`<option value="${w.key}" ${w.key===selectedWeek?'selected':''}>${w.key} · ${dt(w.start)} – ${dt(w.end)}</option>`).join('')}</select><button class="button secondary small" id="nextWeek">→</button></div><div class="inline"><button class="button secondary small" id="clearWeek">Clear this week’s load overrides</button></div></div><div class="banner info"><strong>${state.settings.mode==='suggested'?'Suggested loads':'Manual loads'}.</strong> ${state.settings.mode==='suggested'?'Blank cart inputs use the suggested mix. Enter either cart count to override that day’s complete mix.':'Blank cart inputs mean no carts load.'} Green cells record actual closing ready-stock counts; a count corrects stock from that date onward. This does not erase unserved demand.</div><div class="card table-card"><div class="card-head"><h2>Loads and closing counts</h2><span class="chip">Whole carts only</span></div><p class="table-note">Edit load requests here. Capacity-blocked carts do not enter curing and must be rescheduled.</p><div class="scroll"><table><thead><tr><th>Date / WJ</th><th>Load thin</th><th>Load thick</th><th>Accepted carts</th><th>Oven thin / thick</th><th>Ready thin</th><th>Actual thin</th><th>Ready thick</th><th>Actual thick</th><th>Status</th></tr></thead><tbody>${rows.map(r=>{const d=state.daily[r.date]||{};return `<tr><td class="datecell"><strong>${dt(r.date)}</strong><span>${r.closed?'Shutdown':'Open'} · ${r.manual?'Manual mix':'Suggested'}</span></td>${kinds.map(k=>`<td><input class="entry" type="number" min="0" step="1" data-day="${r.date}" data-dayfield="${k}" value="${d[k]??''}" placeholder="${state.settings.mode==='suggested'?r.accepted[k]:0}" aria-label="${r.date} ${k} cart loads"></td>`).join('')}<td>${r.accepted.thin} / ${r.accepted.thick}</td><td>${r.oven.thin} / ${r.oven.thick}</td><td>${fmt(r.inv.thin)}</td><td><input class="entry actual" type="number" min="0" step="any" data-day="${r.date}" data-dayfield="countThin" value="${d.countThin??''}" placeholder="—" aria-label="${r.date} actual thin closing count"></td><td>${fmt(r.inv.thick)}</td><td><input class="entry actual" type="number" min="0" step="any" data-day="${r.date}" data-dayfield="countThick" value="${d.countThick??''}" placeholder="—" aria-label="${r.date} actual thick closing count"></td><td class="status-text">${r.flags.map(esc).join(' · ')||'<span class="thin-color">Within plan limits</span>'}</td></tr>`}).join('')}</tbody></table></div></div><div class="card table-card" style="margin-top:20px"><div class="card-head"><h2>Daily material balance</h2></div><div class="scroll"><table><thead><tr><th>Date</th><th>Akro</th><th>Opening</th><th>Cured receipts</th><th>Pallets released</th><th>New demand</th><th>Withdrawn</th><th>Count adjustment</th><th>Closing ready</th><th>Waiting for pallet</th><th>Unserved</th></tr></thead><tbody>${rows.flatMap(r=>kinds.map(k=>`<tr><td>${dt(r.date)}</td><td>${label(k)}</td><td>${fmt(r.opening[k])}</td><td>${fmt(r.receipt[k])}</td><td>${fmt(r.released[k])}</td><td>${fmt(r.demand[k])}</td><td>${fmt(r.used[k])}</td><td>${fmt(r.adjust[k])}</td><td>${fmt(r.inv[k])}</td><td>${fmt(r.waiting[k])}</td><td class="${r.backlog[k]>0?'bad':''}">${fmt(r.backlog[k])}</td></tr>`)).join('')}</tbody></table></div></div>`}
function field(k,title,hint='',type='number',opts=''){const g=state.settings;return `<div class="field"><label for="set-${k}">${title}</label><input id="set-${k}" data-setting="${k}" type="${type}" ${type==='number'?'min="0" step="any"':''} ${opts} value="${g[k]}">${hint?`<p>${hint}</p>`:''}</div>`}
function setup(){const g=state.settings;return `<div class="settings-grid"><div><section class="card"><h3>Planning horizon</h3><div class="fields">${field('start','First forecast date','','date')}${field('end','Last forecast date','','date')}${field('lead','Downstream lead days','Advance Akro withdrawals this many days before the supplied demand week.')}${field('withdrawCap','Withdrawal limit per open day','Combined sheets/day. Zero = no capacity limit; catch-up may be optimistic.')}</div><p class="section-note">Weekly demand is distributed evenly over seven days. Shutdowns stop withdrawals, not demand or cure clocks. Before-start demand is excluded; enter any existing unserved demand below.</p></section><section class="card"><h3>Starting position</h3><div class="fields">${field('thinStart','3/4 inch ready sheets')}${field('thickStart','1 1/8 inch ready sheets')}${field('thinWaiting','3/4 cured sheets in build area')}${field('thickWaiting','1 1/8 cured sheets in build area')}${field('thinBacklog','3/4 existing unserved demand')}${field('thickBacklog','1 1/8 existing unserved demand')}</div><p class="section-note"><label><input type="checkbox" data-setting="verified" ${g.verified?'checked':''}> I have confirmed the starting stock and initial oven loads.</label></p></section><section class="card"><div class="card-head"><h3>Initial carts already in the oven</h3><button class="button small secondary" id="addInitial">+ Load</button></div><p class="section-note">Enter the actual load dates before the first forecast date. Each row may contain several matching carts.</p>${state.initialLoads.length?state.initialLoads.map((x,i)=>`<div class="list-row"><select data-initial="${i}" data-key="kind"><option value="thin" ${x.kind==='thin'?'selected':''}>3/4 inch</option><option value="thick" ${x.kind==='thick'?'selected':''}>1 1/8 inch</option></select><input class="num" type="number" min="1" step="1" value="${x.carts}" data-initial="${i}" data-key="carts" aria-label="Initial carts"><input type="date" value="${x.date}" max="${dateStr(dateNum(g.start)-1)}" data-initial="${i}" data-key="date"><button class="remove" data-removeinitial="${i}" aria-label="Remove initial load">×</button></div>`).join(''):'<p class="empty">No starting oven loads entered.</p>'}</section></div><div><section class="card"><h3>Forming and oven</h3><div class="fields"><div class="field wide"><label>Load planning</label><select data-setting="mode"><option value="suggested" ${g.mode==='suggested'?'selected':''}>Suggest a feasible daily mix</option><option value="manual" ${g.mode==='manual'?'selected':''}>Only load carts entered manually</option></select></div>${field('dailyCarts','Maximum carts formed / loaded per day')}${field('weeklyCarts','Maximum new carts per ISO week')}${field('cartSize','Sheets per oven cart')}${field('batchSize','Sheets per available pallet')}${field('thinCure','3/4 cure duration','Full calendar days; fractional values round up for daily planning.')}${field('thickCure','1 1/8 cure duration','Full calendar days; fractional values round up for daily planning.')}${field('transfer','Transfer delay after unloading','Additional whole days before cured sheets reach the pallet build area.')}${field('totalCarts','Total oven cart limit','Default 9 is a conservative planning assumption.')}${field('thinCarts','Maximum 3/4 carts in oven')}${field('thickCarts','Maximum 1 1/8 carts in oven')}${field('thinTarget','3/4 ready-stock target')}${field('thickTarget','1 1/8 ready-stock target')}</div><p class="section-note"><strong>Daily timing:</strong> loads happen at day-end. A cart loaded Monday with a 3-day cure unloads Friday morning; a 5-day cart unloads Sunday morning. The full cure is preserved. Suggested loads target finished stock plus near-term demand, count existing replenishment and round supply to full pallets. This rule does not search for an optimal schedule; targets may be exceeded by a pallet increment. They are a forecast, not authorization to bypass Kanban.</p><p class="section-note"><strong>Oven limitation:</strong> cart counts are checked across overlapping cure periods. Physical mixed-cart fit, cart handling and unload order must still be verified on the floor.</p></section><section class="card"><div class="card-head"><h3>Waterjet shutdowns</h3><button class="button small secondary" id="addShutdown">+ Shutdown</button></div><p class="section-note">Both start and end dates are included. Multiple or overlapping shutdowns are supported.</p>${state.shutdowns.length?state.shutdowns.map((x,i)=>`<div class="list-row"><input type="date" data-shutdown="${i}" data-key="start" value="${x.start}" aria-label="Shutdown start"><span>to</span><input type="date" data-shutdown="${i}" data-key="end" value="${x.end}" aria-label="Shutdown end"><button class="remove" data-removeshutdown="${i}" aria-label="Remove shutdown">×</button></div>`).join(''):'<p class="empty">No shutdown dates set.</p>'}</section><section class="card"><h3>Source and model notes</h3><p class="section-note">Demand source: your pasted November 2 table; 16 parts, 19 supplied weeks, 2,603.45 sheet equivalents. 787 parts default to 1 1/8 inch; other parts default to 3/4 inch. Confirm any exceptions on Weekly demand. Parts sharing a thickness are assumed interchangeable at the cured-sheet stage.</p><p class="section-note">Capacity defaults: 2 new carts/day, 12/week, 20 sheets/cart, 40 sheets/pallet; targets 120 thin and 360 thick sheets. Starting stock and oven loads are not assumed from older plans.</p><details><summary>How balances work</summary><p>Closing ready = opening ready + completed-pallet releases − withdrawals + physical-count adjustment. Cured receipts stay in the build area until a full pallet can be assembled. A shutdown leaves stock untouched and builds unserved demand; open days draw the oldest demand first, subject to stock and withdrawal capacity. Daily demand uses sheet equivalents without rounding each order to a cart.</p><p>Actual closing counts rebase physical stock; they do not certify order completion or delete demand. Load requests beyond daily, weekly or oven limits are flagged and not loaded. Initial loads before the horizon are included separately from new weekly forming capacity.</p></details><button class="button danger small" id="reset" style="margin-top:18px">Reset to supplied demand and defaults</button></section></div></div>`}
function render(){result=simulate(state);$('#error').hidden=true;if(!result.weeks.some(w=>w.key===selectedWeek))selectedWeek=result.weeks[0].key;$('#pageTitle').textContent=titles[tab][0];$('#pageSub').textContent=titles[tab][1];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#app').innerHTML=({overview,demand,daily,setup})[tab]();attachCharts()}
function attachCharts(){document.querySelectorAll('[data-chart]').forEach(svg=>{svg.addEventListener('mousemove',e=>{const dates=svg.dataset.dates.split(','),rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*560,i=Math.max(0,Math.min(dates.length-1,Math.round((x-35)/(560-50)*(dates.length-1)))),r=result.rows.find(r=>r.date===dates[i]),k=svg.dataset.chart;$('#hover-'+k).textContent=`${dt(r.date,true)} · Ready ${fmt(r.inv[k])} · In replenishment ${fmt(r.pipeline[k])} · Unserved ${fmt(r.backlog[k])}${r.closed?' · Waterjet shut down':''}`})})}
document.addEventListener('change',e=>{const t=e.target,d=t.dataset;
 if(d.setting){change(()=>{state.settings[d.setting]=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value;if(d.setting==='start'||d.setting==='end')state.settings.asOf=state.settings.start});return}
 if(d.demand!=null){change(()=>{const p=state.parts[+d.demand];if(demandMode==='qty'){p.qty[d.week]=Number(t.value);delete p.overrides[d.week]}else if(t.value==='')delete p.overrides[d.week];else p.overrides[d.week]=Number(t.value)});return}
 if(d.factor!=null){change(()=>state.parts[+d.factor].factor=Number(t.value));return}
 if(d.thickness!=null){change(()=>state.parts[+d.thickness].thickness=t.value);return}
 if(d.day){change(()=>{const o=state.daily[d.day]||(state.daily[d.day]={});if(['thin','thick'].includes(d.dayfield)&&t.value!==''){const r=result.rows.find(r=>r.date===d.day);for(const k of kinds)if(o[k]==null)o[k]=r.accepted[k]}if(t.value==='')delete o[d.dayfield];else o[d.dayfield]=Number(t.value)});return}
 if(d.initial!=null){change(()=>state.initialLoads[+d.initial][d.key]=d.key==='carts'?Number(t.value):t.value);return}
 if(d.shutdown!=null){change(()=>state.shutdowns[+d.shutdown][d.key]=t.value);return}
 if(t.id==='dailyWeek'){selectedWeek=t.value;render()}if(t.id==='demandMode'){demandMode=t.value;render()}if(t.id==='chartDays'){chartDays=Number(t.value);render()}
 if(t.id==='restore'){const file=t.files[0];if(file)file.text().then(tx=>{const candidate=applyPreloads(validate(JSON.parse(tx)));change(()=>state=candidate);notice('Backup imported.')}).catch(e=>notice('Import failed: '+e.message));t.value=''}
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.id,d=b.dataset;
 if(d.tab){tab=d.tab;render();return}
 if(id==='backup')download(`Akro_Planner_Backup_${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));
 if(id==='csv'){const head=['Date','Week','WJ_shutdown','Thin_new_demand','Thick_new_demand','Thin_loaded_carts','Thick_loaded_carts','Thin_pallet_release','Thick_pallet_release','Thin_withdrawn','Thick_withdrawn','Thin_ready','Thick_ready','Thin_unserved','Thick_unserved','Thin_cured_waiting','Thick_cured_waiting','Thin_count_adjustment','Thick_count_adjustment'];const lines=result.rows.map(r=>[r.date,r.key,+r.closed,r.demand.thin,r.demand.thick,r.accepted.thin,r.accepted.thick,r.released.thin,r.released.thick,r.used.thin,r.used.thick,r.inv.thin,r.inv.thick,r.backlog.thin,r.backlog.thick,r.waiting.thin,r.waiting.thick,r.adjust.thin,r.adjust.thick].join(','));download('Akro_Daily_Projection.csv',[head.join(','),...lines].join('\n'),'text/csv')}
 if(id==='allWeeks'){showAll=!showAll;render()}if(id==='prevWeek'||id==='nextWeek'){let i=result.weeks.findIndex(w=>w.key===selectedWeek);selectedWeek=result.weeks[Math.max(0,Math.min(result.weeks.length-1,i+(id==='nextWeek'?1:-1)))].key;render()}
 if(id==='clearWeek')change(()=>{for(const r of result.rows.filter(r=>r.key===selectedWeek)){const o=state.daily[r.date];if(o){delete o.thin;delete o.thick}}});
 if(id==='addInitial')change(()=>state.initialLoads.push({kind:'thick',carts:1,date:dateStr(dateNum(state.settings.start)-1)}));
 if(id==='addShutdown')change(()=>state.shutdowns.push({start:state.settings.start,end:state.settings.start}));
 if(d.removeinitial!=null)change(()=>state.initialLoads.splice(+d.removeinitial,1));if(d.removeshutdown!=null)change(()=>state.shutdowns.splice(+d.removeshutdown,1));
 if(id==='reset'){modal('<h2>Reset the planner?</h2><p>This replaces this browser’s entries with the supplied demand and default assumptions. Export a backup first if you need the current plan.</p><button class="button danger" id="confirmReset">Reset planner</button>')}
 if(id==='confirmReset'){change(()=>state=defaults(seed));$('#dialog').close();notice('Defaults restored.')}
 if(id==='addWeek')modal(`<h2>Add a demand week</h2><p>Choose any date in the week. It will be stored as its ISO Monday–Sunday week.</p><div class="field"><label>Date in week</label><input id="newWeek" type="date" value="${state.settings.start}"></div><button class="button" id="confirmWeek" style="margin-top:16px">Add week</button>`);
 if(id==='confirmWeek'){const date=$('#newWeek').value,key=weekKey(date);change(()=>{if(state.weeks.some(w=>w.key===key))throw Error('That week is already present.');const [year,w]=key.split('-W');state.weeks.push({key,year:+year,week:+w,date:weekStart(+year,+w)});state.weeks.sort((a,b)=>a.date.localeCompare(b.date))});if(state.weeks.some(w=>w.key===key))$('#dialog').close()}
 if(id==='addPart')modal('<h2>Add a part</h2><div class="fields"><div class="field wide"><label>Part number</label><input id="partId"></div><div class="field"><label>Thickness</label><select id="partKind"><option value="thin">3/4 inch</option><option value="thick">1 1/8 inch</option></select></div><div class="field"><label>Sheets per case</label><input id="partFactor" type="number" min="0.000001" step="any" value="1"></div></div><button class="button" id="confirmPart" style="margin-top:16px">Add part</button>');
 if(id==='confirmPart'){const p={id:$('#partId').value.trim(),thickness:$('#partKind').value,factor:Number($('#partFactor').value),qty:{},overrides:{}};const n=state.parts.length;change(()=>state.parts.push(p));if(state.parts.length>n)$('#dialog').close()}
 if(id==='bulk')modal('<h2>Paste weekly demand</h2><p>Paste CSV or tab-separated rows with headers below. Qty is order quantity; Total_AKRO is already sheets. Leave one blank if unused. Existing parts retain their thickness and factor unless supplied.</p><textarea id="bulkText" aria-label="Weekly demand CSV" placeholder="Year,Week,Part,Qty,Total_AKRO,Thickness,Sheets_per_case\n2026,45,AT-OXB-11,18,,thin,0.8"></textarea><div id="bulkError" class="small"></div><button class="button" id="applyBulk">Validate & import rows</button>');
 if(id==='applyBulk'){try{const rows=parseCSV($('#bulkText').value);const n=importDemand(rows);$('#dialog').close();notice(`${n} demand rows imported.`)}catch(e){$('#bulkError').textContent=e.message;$('#bulkError').style.color='#bc3e4c'}}
});
export function parseCSV(tx){const sep=tx.includes('\t')?'\t':',',rows=[];let row=[],cell='',quoted=false;for(let i=0;i<tx.length;i++){const c=tx[i];if(c==='"'){if(quoted&&tx[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(cell.trim());cell=''}else if(c==='\n'&&!quoted){row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else if(c!=='\r')cell+=c}if(quoted)throw Error('A quoted field is not closed.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function importDemand(rows){if(rows.length<2)throw Error('Include a header and at least one data row.');const h=rows[0].map(v=>v.toLowerCase()),col=n=>h.indexOf(n),get=(r,n)=>r[col(n)]??'';for(const n of ['year','week','part'])if(col(n)<0)throw Error('Required columns: Year, Week, Part, plus Qty or Total_AKRO.');const candidate=structuredClone(state);for(const [i,r]of rows.slice(1).entries()){const year=Number(get(r,'year')),week=Number(get(r,'week')),id=get(r,'part'),qty=get(r,'qty'),ov=get(r,'total_akro');if(!id||!Number.isInteger(year)||year<2020||year>2100||!Number.isInteger(week)||week<1||week>53||(!qty&&!ov))throw Error(`Check year, week, part and demand on row ${i+2}.`);const key=`${year}-W${String(week).padStart(2,'0')}`,date=weekStart(year,week);if(weekKey(date)!==key)throw Error(`Invalid ISO week on row ${i+2}.`);let p=candidate.parts.find(p=>p.id===id);if(!p){p={id,thickness:'',factor:0,qty:{},overrides:{}};candidate.parts.push(p)}let thick=get(r,'thickness');if(thick)p.thickness=['thin','0.75','3/4'].includes(thick.toLowerCase())?'thin':['thick','1.125','1 1/8'].includes(thick.toLowerCase())?'thick':'';if(get(r,'sheets_per_case'))p.factor=Number(get(r,'sheets_per_case'));if(qty!==''){p.qty[key]=Number(qty);delete p.overrides[key]}if(ov!=='')p.overrides[key]=Number(ov);if(!candidate.weeks.some(w=>w.key===key))candidate.weeks.push({key,year,week,date})}candidate.weeks.sort((a,b)=>a.date.localeCompare(b.date));validate(candidate);change(()=>state=candidate);return rows.length-1}
render();save();
